struct PlayerView: View {                     // container: single source of truth
    let episode: Episode                     // read-only input
    @State private var isPlaying = false
    var body: some View {
        VStack { Text(episode.title); PlayButton(isPlaying: $isPlaying) }
    }
}
struct PlayButton: View {                    // stateless child: binding only
    @Binding var isPlaying: Bool
    var body: some View { Button("Toggle") { isPlaying.toggle() } }
}

